/**
 *
 * ListboxOptionIndicator is a component that displays the selection indicator (checkmark or checkbox) for each option in the Listbox component.
 *
 * [Live Demo](https://www.primereact.org/listbox/)
 *
 * @module ListboxOptionIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ListboxRootInstance } from './ListboxRoot.types';
/**
 * Defines passthrough(pt) options type in ListboxOptionIndicator component.
 */
export type ListboxOptionIndicatorPassThroughType<E> = PassThroughType<ListboxOptionIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of ListboxOptionIndicator component.
 */
export interface ListboxOptionIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ListboxOptionIndicatorPassThroughType<React.HTMLAttributes<HTMLElement>>;
}
/**
 * Defines valid properties in ListboxOptionIndicator component.
 * @template T The type of the option data.
 */
export interface ListboxOptionIndicatorProps<T = unknown> extends BaseComponentProps<ListboxOptionIndicatorInstance<T>, unknown, ListboxOptionIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the selection state of the option.
     * - "always": Indicator is always visible.
     * - "selected": Indicator is visible only when the option is selected.
     * - "unselected": Indicator is visible only when the option is not selected.
     * @defaultValue 'always'
     */
    match?: 'always' | 'selected' | 'unselected';
}
/**
 * Defines valid state in ListboxOptionIndicator component.
 */
export interface ListboxOptionIndicatorState {
}
/**
 * Defines the methods and properties exposed by ListboxOptionIndicator component.
 * @template T The type of the option data.
 */
export interface ListboxOptionIndicatorExposes<T = unknown> {
    /**
     * The ListboxOptionIndicator component instance.
     */
    listbox: ListboxRootInstance<T> | undefined | null;
    /**
     * The option data object.
     */
    option: T;
    /**
     * The index of the option in the list.
     */
    index: number | undefined;
    /**
     * Whether this option is a group header.
     */
    group: boolean | undefined;
    /**
     * Whether this option is currently selected.
     */
    selected: boolean | undefined;
}
/**
 * Instance of ListboxOptionIndicator component.
 * @template T The type of the option data.
 */
export type ListboxOptionIndicatorInstance<T = unknown> = ComponentInstance<ListboxOptionIndicatorProps<T>, ListboxOptionIndicatorState, ListboxOptionIndicatorExposes<T>>;
